"""Fail if a tracked source file has no SPDX licence header in its first lines.

Usage: check_spdx.py [FILE ...]   (default: every file tracked by git)
"""

import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

SOURCE_SUFFIXES = {
    ".py", ".c", ".h", ".cc", ".cpp", ".hpp", ".js", ".ts", ".tsx",
    ".sh", ".toml", ".cmake", ".yml", ".yaml", ".xml", ".urdf", ".xacro", ".launch",
}
SOURCE_NAMES = {"CMakeLists.txt", "Dockerfile", "Kconfig", "Kconfig.projbuild", "requirements-dev.txt"}

# Generated by external tools (Beads, agent setups) rather than written for the project
EXCLUDED_PREFIXES = (".beads/", ".agents/", ".claude/", ".codex/")

ALLOWED = {"Apache-2.0", "CERN-OHL-P-2.0", "CC-BY-4.0"}
HEADER_LINES = 5


def tracked_files():
    out = subprocess.run(
        ["git", "ls-files", "--cached", "--others", "--exclude-standard"],
        cwd=ROOT, capture_output=True, text=True, check=True,
    ).stdout
    return [ROOT / line for line in out.splitlines() if line]


def is_source(path):
    rel = path.relative_to(ROOT).as_posix()
    if rel.startswith(EXCLUDED_PREFIXES):
        return False
    return path.suffix in SOURCE_SUFFIXES or path.name in SOURCE_NAMES


def check(path):
    """Return None if the header is fine, else a reason string."""
    with open(path, encoding="utf-8", errors="replace") as f:
        head = [next(f, "") for _ in range(HEADER_LINES)]
    for line in head:
        if "SPDX-License-Identifier:" in line:
            licence = line.split("SPDX-License-Identifier:", 1)[1].strip().rstrip("*/-> ").strip()
            return None if licence in ALLOWED else f"licence '{licence}' not one of {sorted(ALLOWED)}"
    return "missing SPDX-License-Identifier header"


def main(argv):
    files = [Path(a).resolve() for a in argv] if argv else tracked_files()
    failures = [(p, reason) for p in files if p.is_file() and is_source(p) and (reason := check(p))]
    for path, reason in failures:
        print(f"FAIL {path.relative_to(ROOT)}: {reason}")
    checked = sum(1 for p in files if p.is_file() and is_source(p))
    print(f"{checked} source file(s) checked, {len(failures)} failure(s)")
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
